// Skrip penambah fitur login (email + kata sandi) untuk proyek ifs24005-pabwe2026-proyek1.
// Jalankan dari folder root proyek:  node tambah-login.mjs
import { existsSync, mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';

const FILES = {
 "vercel.json": "{\n  \"$schema\": \"https://openapi.vercel.sh/vercel.json\",\n  \"buildCommand\": \"npm run build\",\n  \"outputDirectory\": \"frontend/dist\",\n  \"rewrites\": [\n    {\n      \"source\": \"/api/:path*\",\n      \"destination\": \"/api/index.js\"\n    },\n    {\n      \"source\": \"/((?!api/).*)\",\n      \"destination\": \"/index.html\"\n    }\n  ],\n  \"functions\": {\n    \"api/index.js\": {\n      \"includeFiles\": \"backend/src/db/*.sql\"\n    }\n  }\n}\n",
 "frontend/src/App.vue": "<script setup>\nimport AppHeader from './components/AppHeader.vue';\n</script>\n\n<template>\n  <a class=\"skip-link\" href=\"#konten\">Lewati ke konten utama</a>\n  <AppHeader />\n\n  <main id=\"konten\" tabindex=\"-1\">\n    <RouterView />\n  </main>\n</template>\n\n<style scoped>\nmain:focus {\n  outline: none;\n}\n</style>\n",
 "frontend/src/router.js": "import { createRouter, createWebHistory, START_LOCATION } from 'vue-router';\nimport { nextTick } from 'vue';\nimport { auth, initAuth } from './auth.js';\n\nexport const routes = [\n  { path: '/', name: 'home', component: () => import('./views/HomeView.vue'), meta: { title: 'Beranda' } },\n  { path: '/auth/login', name: 'login', component: () => import('./views/LoginView.vue'), meta: { title: 'Masuk' } },\n  { path: '/produk', name: 'products', component: () => import('./views/ProductsView.vue'), meta: { title: 'Produk', requiresAuth: true } },\n  { path: '/jurnal', name: 'journal', component: () => import('./views/JournalView.vue'), meta: { title: 'Jurnal Kulit', requiresAuth: true } },\n  { path: '/ringkasan', name: 'summary', component: () => import('./views/SummaryView.vue'), meta: { title: 'Ringkasan', requiresAuth: true } },\n  { path: '/profil', name: 'profile', component: () => import('./views/ProfileView.vue'), meta: { title: 'Profil', requiresAuth: true } },\n  { path: '/:pathMatch(.*)*', name: 'not-found', component: () => import('./views/NotFoundView.vue'), meta: { title: 'Halaman tidak ditemukan' } },\n];\n\n// Hanya path internal yang boleh dipakai sebagai tujuan setelah login (cegah open redirect)\nexport function safeRedirect(value, fallback = '/produk') {\n  return typeof value === 'string' && value.startsWith('/') && !value.startsWith('//') ? value : fallback;\n}\n\n// Mengembalikan true (lanjut) atau lokasi tujuan pengganti\nexport function authGuard(to, state = auth) {\n  if (to.meta?.requiresAuth && !state.user) {\n    return { name: 'login', query: { redirect: to.fullPath } };\n  }\n  return true;\n}\n\nexport function createAppRouter(history = createWebHistory()) {\n  const router = createRouter({ history, routes });\n\n  router.beforeEach(async (to) => {\n    await initAuth();\n    return authGuard(to);\n  });\n\n  router.afterEach((to, from) => {\n    if (typeof document === 'undefined') return;\n    document.title = `${to.meta.title} · Skincare Tracker`;\n    // Pindahkan fokus ke konten utama agar pembaca layar tahu halaman sudah berganti\n    if (from !== START_LOCATION) nextTick(() => document.getElementById('konten')?.focus());\n  });\n\n  return router;\n}\n",
 "frontend/src/collection.js": "import { reactive } from 'vue';\nimport { api } from './api.js';\nimport { summarize } from './utils/format.js';\n\n// Data produk dan jurnal yang dipakai bersama halaman Produk, Jurnal, dan Ringkasan.\nexport const collection = reactive({\n  products: [],\n  routines: [],\n  loading: false,\n  message: { type: '', text: '' },\n});\n\nexport function notify(type, text) {\n  collection.message = { type, text };\n}\n\nexport async function loadAll() {\n  collection.loading = true;\n  try {\n    const [products, routines] = await Promise.all([api.listProducts(), api.listRoutines()]);\n    collection.products = products;\n    collection.routines = routines;\n  } catch (error) {\n    // 401 sudah ditangani handler sesi habis (kembali ke halaman login)\n    if (error.status !== 401) notify('error', `Gagal memuat data: ${error.message}`);\n  } finally {\n    collection.loading = false;\n  }\n}\n\nexport function getStats() {\n  return summarize(collection.products, collection.routines);\n}\n\nexport function resetCollection() {\n  collection.products = [];\n  collection.routines = [];\n  collection.loading = false;\n  notify('', '');\n}\n",
 "frontend/src/api.js": "const BASE = import.meta.env?.VITE_API_BASE_URL || '/api';\n\n// Dipanggil saat API membalas 401 untuk endpoint data (sesi habis), diatur di main.js\nlet onUnauthorized = null;\nexport function setUnauthorizedHandler(handler) {\n  onUnauthorized = handler;\n}\n\nasync function request(path, { method = 'GET', body } = {}) {\n  const response = await fetch(`${BASE}${path}`, {\n    method,\n    headers: { 'Content-Type': 'application/json' },\n    body: body === undefined ? undefined : JSON.stringify(body),\n  });\n\n  let payload = null;\n  try {\n    payload = await response.json();\n  } catch {\n    // respons bukan JSON, ditangani di bawah\n  }\n\n  if (!response.ok || !payload || payload.success === false) {\n    const error = new Error(payload?.message || `Permintaan gagal (${response.status})`);\n    error.status = response.status;\n    error.details = payload?.errors || [];\n    if (response.status === 401 && !path.startsWith('/auth/') && onUnauthorized) onUnauthorized();\n    throw error;\n  }\n  return payload.data;\n}\n\nfunction query(params = {}) {\n  const entries = Object.entries(params).filter(([, v]) => v !== '' && v !== null && v !== undefined);\n  const text = new URLSearchParams(entries).toString();\n  return text ? `?${text}` : '';\n}\n\nexport const api = {\n  login: (body) => request('/auth/login', { method: 'POST', body }),\n  logout: () => request('/auth/logout', { method: 'POST' }),\n  me: () => request('/auth/me'),\n\n  listProducts: (params) => request(`/products${query(params)}`),\n  createProduct: (body) => request('/products', { method: 'POST', body }),\n  updateProduct: (id, body) => request(`/products/${id}`, { method: 'PUT', body }),\n  deleteProduct: (id) => request(`/products/${id}`, { method: 'DELETE' }),\n\n  listRoutines: (params) => request(`/routines${query(params)}`),\n  createRoutine: (body) => request('/routines', { method: 'POST', body }),\n  updateRoutine: (id, body) => request(`/routines/${id}`, { method: 'PUT', body }),\n  deleteRoutine: (id) => request(`/routines/${id}`, { method: 'DELETE' }),\n};\n",
 "frontend/src/auth.js": "import { reactive } from 'vue';\nimport { api } from './api.js';\nimport { resetCollection } from './collection.js';\n\n// State login bersama seluruh aplikasi. Sesi disimpan server dalam cookie httpOnly,\n// jadi di sini hanya ada data pengguna yang sedang masuk.\nexport const auth = reactive({ user: null, ready: false });\n\nlet pending = null;\n\n// Cek sesi ke server satu kali (dipakai route guard sebelum halaman pertama tampil).\nexport function initAuth() {\n  if (!pending) {\n    pending = api\n      .me()\n      .then((data) => {\n        auth.user = data.user;\n      })\n      .catch(() => {\n        auth.user = null;\n      })\n      .finally(() => {\n        auth.ready = true;\n      });\n  }\n  return pending;\n}\n\nexport async function signIn(email, password) {\n  const data = await api.login({ email, password });\n  auth.user = data.user;\n  auth.ready = true;\n  return data.user;\n}\n\n// Selalu membersihkan state di sisi klien, walaupun permintaan logout ke server gagal.\nexport async function signOut() {\n  try {\n    await api.logout();\n  } catch {\n    // Server tidak terjangkau: sesi lokal tetap diakhiri\n  } finally {\n    clearAuth();\n    resetCollection();\n  }\n}\n\nexport function clearAuth() {\n  auth.user = null;\n}\n\n// Hanya untuk pengujian\nexport function resetAuth() {\n  pending = null;\n  auth.user = null;\n  auth.ready = false;\n}\n",
 "frontend/src/main.js": "import { createApp } from 'vue';\nimport App from './App.vue';\nimport { createAppRouter } from './router.js';\nimport { setUnauthorizedHandler } from './api.js';\nimport { clearAuth } from './auth.js';\nimport { resetCollection } from './collection.js';\nimport './styles/global.css';\n\nconst router = createAppRouter();\n\n// Sesi habis saat memakai aplikasi: bersihkan state lalu arahkan ke halaman login\nsetUnauthorizedHandler(() => {\n  clearAuth();\n  resetCollection();\n  router.push({ name: 'login', query: { redirect: router.currentRoute.value.fullPath } });\n});\n\ncreateApp(App).use(router).mount('#app');\n",
 "frontend/src/components/AppHeader.vue": "<script setup>\nimport { useRouter } from 'vue-router';\nimport { auth, signOut } from '../auth.js';\n\nconst router = useRouter();\n\nasync function logout() {\n  await signOut();\n  router.push({ name: 'home' });\n}\n</script>\n\n<template>\n  <header class=\"topbar\">\n    <div class=\"container bar\">\n      <RouterLink to=\"/\" class=\"brand\">\n        <span aria-hidden=\"true\">🎀</span> Skincare Tracker\n      </RouterLink>\n\n      <nav aria-label=\"Navigasi utama\">\n        <ul class=\"links\">\n          <li><RouterLink to=\"/\">Beranda</RouterLink></li>\n          <template v-if=\"auth.user\">\n            <li><RouterLink to=\"/produk\">Produk</RouterLink></li>\n            <li><RouterLink to=\"/jurnal\">Jurnal Kulit</RouterLink></li>\n            <li><RouterLink to=\"/ringkasan\">Ringkasan</RouterLink></li>\n            <li><RouterLink to=\"/profil\">Profil</RouterLink></li>\n            <li><button type=\"button\" class=\"btn btn--ghost\" @click=\"logout\">Keluar</button></li>\n          </template>\n          <li v-else><RouterLink to=\"/auth/login\" class=\"login-link\">Masuk</RouterLink></li>\n        </ul>\n      </nav>\n    </div>\n  </header>\n</template>\n\n<style scoped>\n.topbar {\n  background: var(--white);\n  border-bottom: 1px solid var(--pink-200);\n}\n.bar {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  gap: 0.75rem 1.5rem;\n  flex-wrap: wrap;\n  padding: 0.6rem 0;\n}\n.brand {\n  font-family: var(--font-display);\n  font-size: 1.25rem;\n  font-weight: 700;\n  color: var(--plum-900);\n  text-decoration: none;\n}\n.links {\n  list-style: none;\n  margin: 0;\n  padding: 0;\n  display: flex;\n  align-items: center;\n  gap: 0.35rem;\n  flex-wrap: wrap;\n}\n.links a {\n  display: inline-flex;\n  align-items: center;\n  min-height: 44px;\n  padding: 0.3rem 1rem;\n  border-radius: 999px;\n  font-weight: 600;\n  color: var(--plum-900);\n  text-decoration: none;\n}\n.links a:hover {\n  background: var(--lilac-100);\n}\n.links a.router-link-exact-active {\n  background: var(--plum-700);\n  color: var(--white);\n}\n.links a.login-link:not(.router-link-exact-active) {\n  background: var(--rose-700);\n  color: var(--white);\n}\n</style>\n",
 "frontend/src/components/NoticeBar.vue": "<script setup>\nimport { collection, notify } from '../collection.js';\n</script>\n\n<template>\n  <p\n    v-if=\"collection.message.text\"\n    class=\"notice\"\n    :class=\"`notice--${collection.message.type}`\"\n    :role=\"collection.message.type === 'error' ? 'alert' : 'status'\"\n  >\n    <span>{{ collection.message.text }}</span>\n    <button type=\"button\" class=\"btn btn--ghost\" @click=\"notify('', '')\">Tutup</button>\n  </p>\n</template>\n\n<style scoped>\n.notice {\n  display: flex;\n  justify-content: space-between;\n  align-items: center;\n  gap: 1rem;\n  flex-wrap: wrap;\n  padding: 0.75rem 1rem;\n  border-radius: var(--radius);\n  border: 1px solid currentColor;\n  font-weight: 500;\n}\n.notice--success {\n  background: var(--ok-bg);\n  color: var(--ok-fg);\n}\n.notice--error {\n  background: var(--danger-bg);\n  color: var(--danger-fg);\n}\n</style>\n",
 "frontend/src/components/PageHero.vue": "<script setup>\ndefineProps({\n  title: { type: String, required: true },\n  subtitle: { type: String, default: '' },\n});\n</script>\n\n<template>\n  <div class=\"hero\">\n    <div class=\"container\">\n      <p class=\"eyebrow\" aria-hidden=\"true\">✿ ・ 🎀 ・ ✿</p>\n      <h1>{{ title }}</h1>\n      <p v-if=\"subtitle\" class=\"subtitle\">{{ subtitle }}</p>\n    </div>\n  </div>\n</template>\n\n<style scoped>\n.hero {\n  padding: 2.5rem 0 1.5rem;\n  text-align: center;\n  background: linear-gradient(135deg, var(--pink-100), var(--lilac-100) 60%, var(--peach-100));\n  border-bottom: 2px dotted var(--rose-700);\n}\n.eyebrow {\n  color: var(--rose-700);\n  letter-spacing: 0.35em;\n  margin-bottom: 0.5rem;\n}\nh1 {\n  font-size: clamp(1.7rem, 4vw, 2.6rem);\n  font-weight: 700;\n}\n.subtitle {\n  max-width: 40rem;\n  margin: 0.75rem auto 0;\n  color: var(--plum-700);\n}\n</style>\n",
 "frontend/src/views/ProductsView.vue": "<script setup>\nimport { onMounted, onUnmounted, ref } from 'vue';\nimport { api } from '../api.js';\nimport PageHero from '../components/PageHero.vue';\nimport NoticeBar from '../components/NoticeBar.vue';\nimport ProductList from '../components/ProductList.vue';\nimport ModalDialog from '../components/ModalDialog.vue';\nimport ProductForm from '../components/ProductForm.vue';\nimport { collection, loadAll, notify } from '../collection.js';\n\nconst dialog = ref({ open: false, item: null });\n\nonMounted(loadAll);\nonUnmounted(() => notify('', ''));\n\nfunction openDialog(item = null) {\n  dialog.value = { open: true, item };\n}\nfunction closeDialog() {\n  dialog.value = { open: false, item: null };\n}\n\nasync function onSaved() {\n  const editing = Boolean(dialog.value.item);\n  closeDialog();\n  await loadAll();\n  notify('success', editing ? 'Produk berhasil diperbarui ✿' : 'Produk berhasil ditambahkan ✿');\n}\n\nasync function remove(product) {\n  if (!window.confirm(`Hapus \"${product.name}\"? Semua catatan jurnal produk ini juga akan terhapus.`)) return;\n  try {\n    await api.deleteProduct(product.id);\n    await loadAll();\n    notify('success', 'Produk berhasil dihapus.');\n  } catch (error) {\n    if (error.status !== 401) notify('error', `Gagal menghapus produk: ${error.message}`);\n  }\n}\n</script>\n\n<template>\n  <PageHero title=\"Produk Skincare\" subtitle=\"Kelola koleksi produkmu dan pantau tanggal kedaluwarsanya.\" />\n\n  <div class=\"container page\">\n    <NoticeBar />\n    <ProductList\n      :products=\"collection.products\"\n      :loading=\"collection.loading\"\n      @add=\"openDialog()\"\n      @edit=\"openDialog($event)\"\n      @remove=\"remove\"\n    />\n  </div>\n\n  <ModalDialog :open=\"dialog.open\" :title=\"dialog.item ? 'Ubah produk' : 'Tambah produk'\" @close=\"closeDialog\">\n    <ProductForm :item=\"dialog.item\" @saved=\"onSaved\" @cancel=\"closeDialog\" />\n  </ModalDialog>\n</template>\n",
 "frontend/src/views/JournalView.vue": "<script setup>\nimport { onMounted, onUnmounted, ref } from 'vue';\nimport { api } from '../api.js';\nimport PageHero from '../components/PageHero.vue';\nimport NoticeBar from '../components/NoticeBar.vue';\nimport RoutineJournal from '../components/RoutineJournal.vue';\nimport ModalDialog from '../components/ModalDialog.vue';\nimport RoutineForm from '../components/RoutineForm.vue';\nimport { collection, loadAll, notify } from '../collection.js';\n\nconst dialog = ref({ open: false, item: null });\n\nonMounted(loadAll);\nonUnmounted(() => notify('', ''));\n\nfunction openDialog(item = null) {\n  dialog.value = { open: true, item };\n}\nfunction closeDialog() {\n  dialog.value = { open: false, item: null };\n}\n\nasync function onSaved() {\n  const editing = Boolean(dialog.value.item);\n  closeDialog();\n  await loadAll();\n  notify('success', editing ? 'Catatan berhasil diperbarui ✿' : 'Catatan berhasil ditambahkan ✿');\n}\n\nasync function remove(entry) {\n  if (!window.confirm('Hapus catatan jurnal ini?')) return;\n  try {\n    await api.deleteRoutine(entry.id);\n    await loadAll();\n    notify('success', 'Catatan berhasil dihapus.');\n  } catch (error) {\n    if (error.status !== 401) notify('error', `Gagal menghapus catatan: ${error.message}`);\n  }\n}\n</script>\n\n<template>\n  <PageHero title=\"Jurnal Kulit\" subtitle=\"Tulis kondisi kulitmu setiap hari bersama produk yang dipakai.\" />\n\n  <div class=\"container page\">\n    <NoticeBar />\n    <RoutineJournal\n      :routines=\"collection.routines\"\n      :products=\"collection.products\"\n      :loading=\"collection.loading\"\n      @add=\"openDialog()\"\n      @edit=\"openDialog($event)\"\n      @remove=\"remove\"\n    />\n  </div>\n\n  <ModalDialog :open=\"dialog.open\" :title=\"dialog.item ? 'Ubah catatan jurnal' : 'Tambah catatan jurnal'\" @close=\"closeDialog\">\n    <RoutineForm :item=\"dialog.item\" :products=\"collection.products\" @saved=\"onSaved\" @cancel=\"closeDialog\" />\n  </ModalDialog>\n</template>\n",
 "frontend/src/views/ProfileView.vue": "<script setup>\nimport { useRouter } from 'vue-router';\nimport PageHero from '../components/PageHero.vue';\nimport { auth, signOut } from '../auth.js';\nimport { formatDate } from '../utils/format.js';\n\nconst router = useRouter();\n\nasync function logout() {\n  await signOut();\n  router.push({ name: 'home' });\n}\n</script>\n\n<template>\n  <PageHero title=\"Profil\" subtitle=\"Informasi akun yang sedang masuk.\" />\n\n  <div class=\"container page narrow\">\n    <section v-if=\"auth.user\" class=\"card\" aria-labelledby=\"akun-heading\">\n      <h2 id=\"akun-heading\">Data akun</h2>\n      <dl class=\"meta\">\n        <div>\n          <dt>Nama</dt>\n          <dd>{{ auth.user.name }}</dd>\n        </div>\n        <div>\n          <dt>Email</dt>\n          <dd>{{ auth.user.email }}</dd>\n        </div>\n        <div>\n          <dt>Terdaftar sejak</dt>\n          <dd>{{ formatDate(auth.user.created_at?.slice(0, 10)) }}</dd>\n        </div>\n      </dl>\n      <div>\n        <button type=\"button\" class=\"btn btn--ghost\" @click=\"logout\">Keluar</button>\n      </div>\n    </section>\n  </div>\n</template>\n\n<style scoped>\n.narrow {\n  max-width: 560px;\n}\n.card {\n  display: grid;\n  gap: 1rem;\n  padding: 1.5rem;\n  background: var(--white);\n  border: 1px solid var(--pink-200);\n  border-radius: var(--radius);\n  box-shadow: var(--shadow);\n}\n.meta {\n  display: grid;\n  gap: 0.75rem;\n  margin: 0;\n}\ndt {\n  font-size: 0.875rem;\n  color: var(--plum-700);\n}\ndd {\n  margin: 0;\n  font-weight: 600;\n  overflow-wrap: anywhere;\n}\n</style>\n",
 "frontend/src/views/LoginView.vue": "<script setup>\nimport { nextTick, reactive, ref } from 'vue';\nimport { useRoute, useRouter } from 'vue-router';\nimport PageHero from '../components/PageHero.vue';\nimport { auth, signIn, signOut } from '../auth.js';\nimport { safeRedirect } from '../router.js';\n\nconst route = useRoute();\nconst router = useRouter();\n\nconst form = reactive({ email: '', password: '' });\nconst fieldErrors = reactive({ email: '', password: '' });\nconst formError = ref('');\nconst showPassword = ref(false);\nconst submitting = ref(false);\n\nconst EMAIL_PATTERN = /^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$/;\n\nfunction validate() {\n  fieldErrors.email = '';\n  fieldErrors.password = '';\n  const email = form.email.trim();\n  if (!email) fieldErrors.email = 'Email wajib diisi';\n  else if (!EMAIL_PATTERN.test(email)) fieldErrors.email = 'Format email tidak valid, contoh: nama@email.com';\n  if (!form.password) fieldErrors.password = 'Kata sandi wajib diisi';\n  return !fieldErrors.email && !fieldErrors.password;\n}\n\nasync function submit() {\n  formError.value = '';\n  if (!validate()) {\n    await nextTick();\n    document.getElementById(fieldErrors.email ? 'email' : 'password')?.focus();\n    return;\n  }\n\n  submitting.value = true;\n  try {\n    await signIn(form.email.trim(), form.password);\n    await router.push(safeRedirect(route.query.redirect));\n  } catch (error) {\n    formError.value = error.details?.length ? error.details.join('. ') : error.message;\n    form.password = '';\n    await nextTick();\n    document.getElementById('password')?.focus();\n  } finally {\n    submitting.value = false;\n  }\n}\n</script>\n\n<template>\n  <PageHero title=\"Masuk\" subtitle=\"Masuk dengan email dan kata sandi untuk mengelola koleksi skincare-mu.\" />\n\n  <div class=\"container page narrow\">\n    <section v-if=\"auth.user\" class=\"card\" aria-labelledby=\"already-heading\">\n      <h2 id=\"already-heading\">Kamu sudah masuk</h2>\n      <p>\n        Masuk sebagai <strong>{{ auth.user.email }}</strong\n        >.\n      </p>\n      <div class=\"actions\">\n        <RouterLink class=\"btn btn--primary\" to=\"/produk\">Buka koleksi produk</RouterLink>\n        <button type=\"button\" class=\"btn btn--ghost\" @click=\"signOut\">Keluar</button>\n      </div>\n    </section>\n\n    <section v-else class=\"card\" aria-labelledby=\"login-heading\">\n      <h2 id=\"login-heading\">Selamat datang kembali</h2>\n\n      <form class=\"form\" novalidate @submit.prevent=\"submit\">\n        <div v-if=\"formError\" class=\"error-box\" role=\"alert\">{{ formError }}</div>\n\n        <div class=\"field\">\n          <label for=\"email\">Email</label>\n          <input\n            id=\"email\"\n            v-model=\"form.email\"\n            class=\"input\"\n            type=\"email\"\n            name=\"email\"\n            autocomplete=\"email\"\n            inputmode=\"email\"\n            required\n            placeholder=\"nama@email.com\"\n            :aria-invalid=\"fieldErrors.email ? 'true' : undefined\"\n            :aria-describedby=\"fieldErrors.email ? 'email-error' : undefined\"\n          />\n          <p v-if=\"fieldErrors.email\" id=\"email-error\" class=\"field-error\">{{ fieldErrors.email }}</p>\n        </div>\n\n        <div class=\"field\">\n          <label for=\"password\">Kata sandi</label>\n          <input\n            id=\"password\"\n            v-model=\"form.password\"\n            class=\"input\"\n            :type=\"showPassword ? 'text' : 'password'\"\n            name=\"password\"\n            autocomplete=\"current-password\"\n            required\n            :aria-invalid=\"fieldErrors.password ? 'true' : undefined\"\n            :aria-describedby=\"fieldErrors.password ? 'password-error' : undefined\"\n          />\n          <p v-if=\"fieldErrors.password\" id=\"password-error\" class=\"field-error\">{{ fieldErrors.password }}</p>\n        </div>\n\n        <div class=\"show\">\n          <input id=\"show-password\" v-model=\"showPassword\" type=\"checkbox\" />\n          <label for=\"show-password\">Tampilkan kata sandi</label>\n        </div>\n\n        <button type=\"submit\" class=\"btn btn--primary\" :disabled=\"submitting\">\n          {{ submitting ? 'Memproses…' : 'Masuk' }}\n        </button>\n      </form>\n    </section>\n  </div>\n</template>\n\n<style scoped>\n.narrow {\n  max-width: 480px;\n}\n.card {\n  display: grid;\n  gap: 1rem;\n  padding: 1.5rem;\n  background: var(--white);\n  border: 1px solid var(--pink-200);\n  border-radius: var(--radius);\n  box-shadow: var(--shadow);\n}\n.form {\n  display: grid;\n  gap: 1rem;\n}\n.field-error {\n  font-size: 0.875rem;\n  font-weight: 500;\n  color: var(--danger-fg);\n}\n.show {\n  display: flex;\n  align-items: center;\n  gap: 0.6rem;\n}\n.show input {\n  width: 1.25rem;\n  height: 1.25rem;\n  accent-color: var(--rose-700);\n}\n.actions {\n  display: flex;\n  gap: 0.75rem;\n  flex-wrap: wrap;\n}\n</style>\n",
 "frontend/src/views/HomeView.vue": "<script setup>\nimport PageHero from '../components/PageHero.vue';\nimport { auth } from '../auth.js';\n\nconst features = [\n  { title: 'Pantau kedaluwarsa', text: 'Badge otomatis menandai produk yang masih aman, hampir habis masa pakainya, atau sudah kedaluwarsa.' },\n  { title: 'Jurnal kulit harian', text: 'Catat produk yang dipakai pagi dan malam, kondisi kulit, serta nilai 1 sampai 5.' },\n  { title: 'Ringkasan koleksi', text: 'Lihat sekilas jumlah produk, yang segera kedaluwarsa, dan total catatan jurnal.' },\n];\n</script>\n\n<template>\n  <PageHero\n    title=\"Skincare Routine & Inventory Tracker\"\n    subtitle=\"Catat koleksi skincare-mu, pantau tanggal kedaluwarsa, dan tulis jurnal kondisi kulit harian.\"\n  />\n\n  <div class=\"container page\">\n    <section aria-labelledby=\"fitur-heading\">\n      <h2 id=\"fitur-heading\">Yang bisa kamu lakukan</h2>\n      <ul class=\"features\">\n        <li v-for=\"item in features\" :key=\"item.title\" class=\"feature\">\n          <h3>{{ item.title }}</h3>\n          <p>{{ item.text }}</p>\n        </li>\n      </ul>\n    </section>\n\n    <div class=\"cta\">\n      <RouterLink v-if=\"auth.user\" class=\"btn btn--primary\" to=\"/produk\">Buka koleksi produk</RouterLink>\n      <RouterLink v-else class=\"btn btn--primary\" to=\"/auth/login\">Masuk untuk mulai</RouterLink>\n    </div>\n  </div>\n</template>\n\n<style scoped>\nh2 {\n  margin-bottom: 1rem;\n}\n.features {\n  list-style: none;\n  margin: 0;\n  padding: 0;\n  display: grid;\n  grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));\n  gap: 1rem;\n}\n.feature {\n  display: grid;\n  gap: 0.4rem;\n  padding: 1.1rem 1.25rem;\n  background: var(--white);\n  border: 1px solid var(--pink-200);\n  border-radius: var(--radius);\n  box-shadow: var(--shadow);\n}\n.cta {\n  text-align: center;\n}\n</style>\n",
 "frontend/src/views/NotFoundView.vue": "<script setup>\nimport PageHero from '../components/PageHero.vue';\n</script>\n\n<template>\n  <PageHero title=\"Halaman tidak ditemukan\" subtitle=\"Alamat yang kamu buka tidak ada di aplikasi ini.\" />\n  <div class=\"container page\">\n    <p class=\"empty\">Coba kembali ke beranda atau pilih menu di bagian atas.</p>\n    <p><RouterLink class=\"btn btn--primary\" to=\"/\">Kembali ke beranda</RouterLink></p>\n  </div>\n</template>\n",
 "frontend/src/views/SummaryView.vue": "<script setup>\nimport { computed, onMounted } from 'vue';\nimport PageHero from '../components/PageHero.vue';\nimport SummaryCards from '../components/SummaryCards.vue';\nimport ExpiryBadge from '../components/ExpiryBadge.vue';\nimport NoticeBar from '../components/NoticeBar.vue';\nimport { collection, getStats, loadAll } from '../collection.js';\nimport { CATEGORY_LABELS, formatDate } from '../utils/format.js';\n\nonMounted(loadAll);\n\nconst stats = computed(() => getStats());\nconst urgent = computed(() =>\n  collection.products\n    .filter((p) => p.days_left <= 30)\n    .sort((a, b) => a.days_left - b.days_left)\n);\n</script>\n\n<template>\n  <PageHero title=\"Ringkasan\" subtitle=\"Gambaran singkat koleksi skincare dan jurnal kulitmu.\" />\n\n  <div class=\"container page\">\n    <NoticeBar />\n    <SummaryCards :stats=\"stats\" />\n\n    <section aria-labelledby=\"urgent-heading\">\n      <h2 id=\"urgent-heading\">Perlu segera dipakai</h2>\n      <p v-if=\"collection.loading\" class=\"empty\" role=\"status\">Memuat data…</p>\n      <p v-else-if=\"!urgent.length\" class=\"empty\">Tidak ada produk yang mendekati kedaluwarsa. ✿</p>\n      <ul v-else class=\"list\">\n        <li v-for=\"product in urgent\" :key=\"product.id\" class=\"item\">\n          <div>\n            <p class=\"name\">{{ product.name }}</p>\n            <p class=\"sub\">\n              {{ product.brand }} · {{ CATEGORY_LABELS[product.category] || product.category }} · sampai\n              {{ formatDate(product.expiry_date) }}\n            </p>\n          </div>\n          <ExpiryBadge :days-left=\"product.days_left\" />\n        </li>\n      </ul>\n    </section>\n  </div>\n</template>\n\n<style scoped>\nh2 {\n  margin-bottom: 1rem;\n}\n.list {\n  list-style: none;\n  margin: 0;\n  padding: 0;\n  display: grid;\n  gap: 0.75rem;\n}\n.item {\n  display: flex;\n  justify-content: space-between;\n  align-items: center;\n  gap: 0.75rem 1rem;\n  flex-wrap: wrap;\n  padding: 0.9rem 1.1rem;\n  background: var(--white);\n  border: 1px solid var(--pink-200);\n  border-radius: var(--radius);\n}\n.name {\n  font-weight: 600;\n}\n.sub {\n  font-size: 0.875rem;\n  color: var(--plum-700);\n}\n</style>\n",
 "frontend/tests/client-auth.test.js": "import { describe, it, expect, beforeEach, afterEach, vi } from 'vitest';\nimport { api, setUnauthorizedHandler } from '../src/api.js';\nimport { auth, initAuth, signIn, signOut, clearAuth, resetAuth } from '../src/auth.js';\nimport { collection, loadAll, notify, getStats, resetCollection } from '../src/collection.js';\nimport { authGuard, safeRedirect, routes, createAppRouter } from '../src/router.js';\nimport { createMemoryHistory } from 'vue-router';\n\n// Konfigurasi vitest di root tidak memuat plugin Vue, jadi file .vue diganti komponen kosong\nvi.mock('../src/views/LoginView.vue', () => ({ default: { render: () => null } }));\nvi.mock('../src/views/ProfileView.vue', () => ({ default: { render: () => null } }));\n\nconst originalFetch = globalThis.fetch;\nlet calls;\n\nconst json = (payload, status = 200) => ({\n  ok: status >= 200 && status < 300,\n  status,\n  json: async () => payload,\n});\n\n// routes: { '/auth/me': respons, ... } dicocokkan dengan akhir URL\nfunction mockApi(routesMap) {\n  calls = [];\n  globalThis.fetch = async (url, options) => {\n    calls.push({ url, options });\n    const key = Object.keys(routesMap).find((k) => url.endsWith(k));\n    return key ? routesMap[key] : json({ success: false, message: 'tidak ada' }, 404);\n  };\n}\n\nconst user = { id: 1, name: 'Pengguna Uji', email: 'admin@skincare.test', created_at: '2026-10-01 08:00:00' };\n\nbeforeEach(() => {\n  resetAuth();\n  resetCollection();\n  setUnauthorizedHandler(null);\n});\nafterEach(() => {\n  globalThis.fetch = originalFetch;\n});\n\ndescribe('api auth', () => {\n  it('mengirim kredensial ke /auth/login lewat POST', async () => {\n    mockApi({ '/auth/login': json({ success: true, data: { user } }) });\n    const data = await api.login({ email: 'a@b.co', password: 'x' });\n    expect(data.user.email).toBe(user.email);\n    expect(calls[0].url).toBe('/api/auth/login');\n    expect(calls[0].options.method).toBe('POST');\n    expect(calls[0].options.body).toBe('{\"email\":\"a@b.co\",\"password\":\"x\"}');\n  });\n\n  it('memanggil handler sesi habis hanya untuk 401 di endpoint data', async () => {\n    let fired = 0;\n    setUnauthorizedHandler(() => (fired += 1));\n    mockApi({\n      '/products': json({ success: false, message: 'Silakan masuk' }, 401),\n      '/auth/login': json({ success: false, message: 'Email atau kata sandi salah' }, 401),\n    });\n    await expect(api.listProducts()).rejects.toThrow('Silakan masuk');\n    expect(fired).toBe(1);\n    await expect(api.login({})).rejects.toThrow('Email atau kata sandi salah');\n    expect(fired).toBe(1);\n  });\n\n  it('tidak error jika tidak ada handler sesi habis', async () => {\n    mockApi({ '/products': json({ success: false, message: 'x' }, 401) });\n    await expect(api.listProducts()).rejects.toThrow('x');\n  });\n});\n\ndescribe('state auth', () => {\n  it('initAuth memuat pengguna dari /auth/me dan hanya memanggil server sekali', async () => {\n    mockApi({ '/auth/me': json({ success: true, data: { user } }) });\n    await Promise.all([initAuth(), initAuth()]);\n    await initAuth();\n    expect(auth.user.email).toBe(user.email);\n    expect(auth.ready).toBe(true);\n    expect(calls).toHaveLength(1);\n  });\n\n  it('initAuth menganggap belum login jika server membalas user null atau error', async () => {\n    mockApi({ '/auth/me': json({ success: true, data: { user: null } }) });\n    await initAuth();\n    expect(auth.user).toBeNull();\n    expect(auth.ready).toBe(true);\n\n    resetAuth();\n    mockApi({ '/auth/me': json({ success: false, message: 'Silakan masuk' }, 401) });\n    await initAuth();\n    expect(auth.user).toBeNull();\n    expect(auth.ready).toBe(true);\n  });\n\n  it('signIn menyimpan pengguna, dan melempar error jika kredensial salah', async () => {\n    mockApi({ '/auth/login': json({ success: true, data: { user } }) });\n    expect((await signIn('admin@skincare.test', 'Admin123!')).name).toBe('Pengguna Uji');\n    expect(auth.user).toEqual(user);\n\n    clearAuth();\n    mockApi({ '/auth/login': json({ success: false, message: 'Email atau kata sandi salah' }, 401) });\n    await expect(signIn('a@b.co', 'x')).rejects.toThrow('Email atau kata sandi salah');\n    expect(auth.user).toBeNull();\n  });\n\n  it('signOut membersihkan pengguna dan data walaupun server gagal dihubungi', async () => {\n    auth.user = user;\n    collection.products = [{ id: 1, days_left: 5 }];\n    globalThis.fetch = async () => {\n      throw new Error('jaringan putus');\n    };\n    await signOut();\n    expect(auth.user).toBeNull();\n    expect(collection.products).toEqual([]);\n  });\n\n  it('signOut memanggil /auth/logout', async () => {\n    auth.user = user;\n    mockApi({ '/auth/logout': json({ success: true, data: { loggedOut: true } }) });\n    await signOut();\n    expect(calls[0].url).toBe('/api/auth/logout');\n    expect(auth.user).toBeNull();\n  });\n});\n\ndescribe('collection', () => {\n  it('loadAll mengisi produk dan jurnal serta menghitung ringkasan', async () => {\n    mockApi({\n      '/products': json({ success: true, data: [{ id: 1, days_left: 10 }, { id: 2, days_left: -3 }, { id: 3, days_left: 200 }] }),\n      '/routines': json({ success: true, data: [{ id: 1 }] }),\n    });\n    await loadAll();\n    expect(collection.loading).toBe(false);\n    expect(getStats()).toEqual({ totalProducts: 3, expiringSoon: 1, expired: 1, totalEntries: 1 });\n  });\n\n  it('loadAll menampilkan pesan error, kecuali untuk 401', async () => {\n    mockApi({ '/products': json({ success: false, message: 'server error' }, 500), '/routines': json({ success: true, data: [] }) });\n    await loadAll();\n    expect(collection.message).toEqual({ type: 'error', text: 'Gagal memuat data: server error' });\n\n    notify('', '');\n    mockApi({ '/products': json({ success: false, message: 'Silakan masuk' }, 401), '/routines': json({ success: false, message: 'Silakan masuk' }, 401) });\n    await loadAll();\n    expect(collection.message.text).toBe('');\n  });\n});\n\ndescribe('router', () => {\n  it('guard mengarahkan tamu ke login dengan tujuan semula, pengguna masuk lolos', () => {\n    const to = { meta: { requiresAuth: true }, fullPath: '/produk?q=wardah' };\n    expect(authGuard(to, { user: null })).toEqual({ name: 'login', query: { redirect: '/produk?q=wardah' } });\n    expect(authGuard(to, { user })).toBe(true);\n    expect(authGuard({ meta: {}, fullPath: '/' }, { user: null })).toBe(true);\n    expect(authGuard({ fullPath: '/' }, { user: null })).toBe(true);\n  });\n\n  it('safeRedirect hanya menerima path internal', () => {\n    expect(safeRedirect('/jurnal')).toBe('/jurnal');\n    expect(safeRedirect('//evil.com')).toBe('/produk');\n    expect(safeRedirect('https://evil.com')).toBe('/produk');\n    expect(safeRedirect(undefined)).toBe('/produk');\n    expect(safeRedirect(['/a'])).toBe('/produk');\n    expect(safeRedirect('x', '/')).toBe('/');\n  });\n\n  it('empat halaman terproteksi dan dua halaman publik terdaftar', () => {\n    const protectedPaths = routes.filter((r) => r.meta.requiresAuth).map((r) => r.path);\n    expect(protectedPaths).toEqual(['/produk', '/jurnal', '/ringkasan', '/profil']);\n    const publicPaths = routes.filter((r) => !r.meta.requiresAuth).map((r) => r.path);\n    expect(publicPaths).toContain('/');\n    expect(publicPaths).toContain('/auth/login');\n  });\n\n  it('router menahan tamu di login dan membiarkan pengguna masuk membuka halaman terproteksi', async () => {\n    mockApi({ '/auth/me': json({ success: true, data: { user: null } }) });\n    const guest = createAppRouter(createMemoryHistory());\n    await guest.push('/ringkasan');\n    expect(guest.currentRoute.value.name).toBe('login');\n    expect(guest.currentRoute.value.query.redirect).toBe('/ringkasan');\n\n    resetAuth();\n    mockApi({ '/auth/me': json({ success: true, data: { user } }) });\n    const member = createAppRouter(createMemoryHistory());\n    await member.push('/profil');\n    expect(member.currentRoute.value.name).toBe('profile');\n  });\n});\n",
 "backend/server.js": "// Entry point back-end: menjalankan REST API dan menyajikan hasil build front-end (frontend/dist).\nimport { fileURLToPath } from 'node:url';\n\n// .env dibaca dari folder tempat perintah dijalankan dan dari folder backend (keduanya opsional).\nfor (const file of ['.env', fileURLToPath(new URL('./.env', import.meta.url))]) {\n  try {\n    process.loadEnvFile?.(file);\n  } catch {\n    // File .env bersifat opsional, nilai default dipakai jika tidak ada.\n  }\n}\n\nconst { openDatabase } = await import('./src/db/database.js');\nconst { createApp } = await import('./src/app.js');\n\nconst PORT = process.env.PORT || process.env.APP_PORT || 3000;\nconst dbPath = process.env.DB_PATH || fileURLToPath(new URL('./data/skincare.db', import.meta.url));\nconst db = openDatabase(dbPath, { seed: process.env.SEED !== 'false' });\nconst staticDir = fileURLToPath(new URL('../frontend/dist', import.meta.url));\n\ncreateApp(db, { staticDir, authSecret: process.env.AUTH_SECRET || undefined }).listen(PORT, () => {\n  console.log(`Server berjalan di http://localhost:${PORT}`);\n});\n",
 "backend/src/app.js": "import express from 'express';\nimport cors from 'cors';\nimport { existsSync } from 'node:fs';\nimport { join } from 'node:path';\nimport { randomBytes } from 'node:crypto';\n\nimport { productRoutes } from './routes/productRoutes.js';\nimport { routineRoutes } from './routes/routineRoutes.js';\nimport { authRoutes } from './routes/authRoutes.js';\nimport { requireAuth } from './middleware/auth.js';\nimport { notFound, errorHandler } from './middleware/errorHandler.js';\n\n// db      : hasil openDatabase()\n// options : staticDir  = folder hasil build Vue (dist). Jika ada, disajikan oleh Express.\n//           authSecret = kunci penanda tangan cookie sesi (AUTH_SECRET). Jika kosong dibuat acak\n//                        sehingga semua sesi berakhir saat server restart.\nexport function createApp(db, { staticDir, authSecret = randomBytes(32).toString('hex') } = {}) {\n  const app = express();\n\n  app.use(cors());\n  app.use(express.json());\n\n  app.get('/api/health', (req, res) => {\n    db.prepare('SELECT 1 AS ok').get();\n    res.json({ success: true, data: { status: 'ok', time: new Date().toISOString() } });\n  });\n\n  app.use('/api/auth', authRoutes(db, authSecret));\n\n  // Semua data skincare hanya untuk pengguna yang sudah masuk\n  const protect = requireAuth(db, authSecret);\n  app.use('/api/products', protect, productRoutes(db));\n  app.use('/api/routines', protect, routineRoutes(db));\n  app.use('/api', notFound);\n\n  if (staticDir && existsSync(join(staticDir, 'index.html'))) {\n    app.use(express.static(staticDir));\n    // Fallback untuk single page app: semua GET non-API mengembalikan index.html\n    app.use((req, res, next) => {\n      if (req.method !== 'GET') return next();\n      return res.sendFile(join(staticDir, 'index.html'));\n    });\n  }\n\n  app.use(notFound);\n  app.use(errorHandler);\n  return app;\n}\n",
 "backend/src/controllers/authController.js": "import { HttpError } from '../utils/httpError.js';\nimport { getSessionUser } from '../middleware/auth.js';\nimport { validateLogin } from '../utils/validators.js';\nimport { DUMMY_HASH, verifyPassword } from '../utils/password.js';\nimport { COOKIE_NAME, SESSION_SECONDS, createToken } from '../utils/session.js';\n\nconst MAX_FAILURES = 5;\nconst WINDOW_MS = 15 * 60 * 1000;\n\nconst publicUser = ({ id, name, email, created_at }) => ({ id, name, email, created_at });\n\nexport function authController(db, secret) {\n  const failures = new Map(); // `${ip}|${email}` -> { count, firstAt }\n\n  const cookieOptions = {\n    httpOnly: true,\n    sameSite: 'lax',\n    secure: process.env.COOKIE_SECURE === 'true' || Boolean(process.env.VERCEL),\n    path: '/',\n  };\n\n  function isLocked(key, now) {\n    const entry = failures.get(key);\n    if (!entry) return false;\n    if (now - entry.firstAt > WINDOW_MS) {\n      failures.delete(key);\n      return false;\n    }\n    return entry.count >= MAX_FAILURES;\n  }\n\n  function recordFailure(key, now) {\n    const entry = failures.get(key);\n    if (!entry || now - entry.firstAt > WINDOW_MS) failures.set(key, { count: 1, firstAt: now });\n    else entry.count += 1;\n  }\n\n  return {\n    login(req, res) {\n      const { email, password } = validateLogin(req.body);\n      const key = `${req.ip}|${email}`;\n      const now = Date.now();\n\n      if (isLocked(key, now)) {\n        throw new HttpError(429, 'Terlalu banyak percobaan masuk. Coba lagi dalam 15 menit.');\n      }\n\n      const user = db.prepare('SELECT * FROM users WHERE email = ?').get(email);\n      const valid = verifyPassword(password, user ? user.password_hash : DUMMY_HASH);\n      if (!user || !valid) {\n        recordFailure(key, now);\n        // Pesan sama untuk email salah dan password salah agar akun tidak bisa ditebak\n        throw new HttpError(401, 'Email atau kata sandi salah');\n      }\n\n      failures.delete(key);\n      res.cookie(COOKIE_NAME, createToken(user.id, secret), {\n        ...cookieOptions,\n        maxAge: SESSION_SECONDS * 1000,\n      });\n      res.json({ success: true, data: { user: publicUser(user) } });\n    },\n\n    logout(req, res) {\n      res.clearCookie(COOKIE_NAME, cookieOptions);\n      res.json({ success: true, data: { loggedOut: true } });\n    },\n\n    // Cek sesi: selalu 200 agar pengunjung yang belum masuk tidak memicu error di console browser\n    me(req, res) {\n      const user = getSessionUser(db, secret, req);\n      res.json({ success: true, data: { user: user ? publicUser(user) : null } });\n    },\n  };\n}\n",
 "backend/src/middleware/auth.js": "import { HttpError } from '../utils/httpError.js';\nimport { COOKIE_NAME, parseCookies, verifyToken } from '../utils/session.js';\n\n// Pengguna dari cookie sesi yang valid, atau undefined jika tidak ada/tidak sah.\nexport function getSessionUser(db, secret, req) {\n  const userId = verifyToken(parseCookies(req.headers.cookie)[COOKIE_NAME], secret);\n  if (!userId) return undefined;\n  return db.prepare('SELECT id, name, email, created_at FROM users WHERE id = ?').get(userId);\n}\n\n// Menempelkan req.user jika cookie sesi valid, jika tidak balas 401.\nexport function requireAuth(db, secret) {\n  return (req, res, next) => {\n    const user = getSessionUser(db, secret, req);\n    if (!user) return next(new HttpError(401, 'Silakan masuk terlebih dahulu'));\n    req.user = user;\n    return next();\n  };\n}\n",
 "backend/src/db/database.js": "import { createRequire } from 'node:module';\nimport { mkdirSync, readFileSync } from 'node:fs';\nimport { dirname } from 'node:path';\nimport { hashPassword } from '../utils/password.js';\n\nconst require = createRequire(import.meta.url);\n\n// SQLite bawaan runtime: bun:sqlite di Bun, node:sqlite di Node.js (>= 22.13).\n// Tidak ada modul native yang perlu dikompilasi, jadi aman untuk Jenkins dan deployment.\nfunction connect(path) {\n  if (typeof Bun !== 'undefined') {\n    const { Database } = require('bun:sqlite');\n    return new Database(path, { strict: true });\n  }\n  const { DatabaseSync } = require('node:sqlite');\n  return new DatabaseSync(path);\n}\n\n// Membungkus statement agar get/all/run berperilaku sama di kedua runtime.\nfunction wrap(raw) {\n  return {\n    exec: (sql) => raw.exec(sql),\n    close: () => raw.close(),\n    prepare(sql) {\n      const stmt = raw.prepare(sql);\n      return {\n        get: (...args) => stmt.get(...args) ?? undefined,\n        all: (...args) => stmt.all(...args),\n        run: (...args) => stmt.run(...args),\n      };\n    },\n  };\n}\n\nconst readSql = (name) => readFileSync(new URL(name, import.meta.url), 'utf8');\n\n// Akun uji untuk login. Ganti lewat SEED_USER_EMAIL dan SEED_USER_PASSWORD di .env.\nfunction seedUser(db) {\n  const { total } = db.prepare('SELECT COUNT(*) AS total FROM users').get();\n  if (total > 0) return;\n  const email = (process.env.SEED_USER_EMAIL || 'admin@skincare.test').trim().toLowerCase();\n  const password = process.env.SEED_USER_PASSWORD || 'Admin123!';\n  db.prepare('INSERT INTO users (name, email, password_hash) VALUES (?, ?, ?)').run(\n    'Pengguna Uji',\n    email,\n    hashPassword(password)\n  );\n}\n\nexport function openDatabase(path = ':memory:', { seed = true } = {}) {\n  if (path !== ':memory:') mkdirSync(dirname(path), { recursive: true });\n\n  const db = wrap(connect(path));\n  db.exec('PRAGMA foreign_keys = ON;'); // wajib agar ON DELETE CASCADE berfungsi\n  db.exec(readSql('./schema.sql'));\n\n  const { total } = db.prepare('SELECT COUNT(*) AS total FROM products').get();\n  if (seed && total === 0) db.exec(readSql('./seed.sql'));\n  if (seed) seedUser(db);\n\n  return db;\n}\n",
 "backend/src/db/schema.sql": "PRAGMA foreign_keys = ON;\n\nCREATE TABLE IF NOT EXISTS users (\n  id            INTEGER PRIMARY KEY AUTOINCREMENT,\n  name          TEXT    NOT NULL,\n  email         TEXT    NOT NULL UNIQUE,\n  password_hash TEXT    NOT NULL,\n  created_at    TEXT    NOT NULL DEFAULT (datetime('now'))\n);\n\nCREATE TABLE IF NOT EXISTS products (\n  id            INTEGER PRIMARY KEY AUTOINCREMENT,\n  name          TEXT    NOT NULL,\n  brand         TEXT    NOT NULL,\n  category      TEXT    NOT NULL\n                CHECK (category IN ('cleanser','toner','serum','moisturizer','sunscreen','mask','other')),\n  opened_date   TEXT,\n  expiry_date   TEXT    NOT NULL,\n  quantity      INTEGER NOT NULL DEFAULT 1 CHECK (quantity >= 0),\n  price         INTEGER,\n  notes         TEXT,\n  created_at    TEXT    NOT NULL DEFAULT (datetime('now')),\n  updated_at    TEXT    NOT NULL DEFAULT (datetime('now'))\n);\n\nCREATE TABLE IF NOT EXISTS routines (\n  id             INTEGER PRIMARY KEY AUTOINCREMENT,\n  product_id     INTEGER NOT NULL,\n  used_at        TEXT    NOT NULL,\n  time_of_day    TEXT    NOT NULL\n                 CHECK (time_of_day IN ('morning','night')),\n  skin_condition TEXT    NOT NULL\n                 CHECK (skin_condition IN ('great','good','normal','dry','oily','breakout','irritated')),\n  skin_rating    INTEGER CHECK (skin_rating BETWEEN 1 AND 5),\n  notes          TEXT,\n  created_at     TEXT    NOT NULL DEFAULT (datetime('now')),\n  FOREIGN KEY (product_id) REFERENCES products(id) ON DELETE CASCADE\n);\n\nCREATE INDEX IF NOT EXISTS idx_routines_product ON routines(product_id);\nCREATE INDEX IF NOT EXISTS idx_routines_used_at ON routines(used_at);\nCREATE INDEX IF NOT EXISTS idx_products_expiry  ON products(expiry_date);\n",
 "backend/src/utils/session.js": "import { createHmac, timingSafeEqual } from 'node:crypto';\n\nexport const COOKIE_NAME = 'session';\nexport const SESSION_SECONDS = 60 * 60 * 24 * 7; // 7 hari\n\nconst sign = (data, secret) => createHmac('sha256', secret).update(data).digest('base64url');\n\n// Token: base64url(JSON{uid, exp}) + '.' + HMAC-SHA256\nexport function createToken(userId, secret, now = Date.now()) {\n  const payload = Buffer.from(\n    JSON.stringify({ uid: userId, exp: Math.floor(now / 1000) + SESSION_SECONDS })\n  ).toString('base64url');\n  return `${payload}.${sign(payload, secret)}`;\n}\n\n// Mengembalikan id pengguna, atau null jika token rusak, dipalsukan, atau kedaluwarsa.\nexport function verifyToken(token, secret, now = Date.now()) {\n  if (typeof token !== 'string') return null;\n  const [payload, signature] = token.split('.');\n  if (!payload || !signature) return null;\n\n  const expected = Buffer.from(sign(payload, secret));\n  const received = Buffer.from(signature);\n  if (expected.length !== received.length || !timingSafeEqual(expected, received)) return null;\n\n  try {\n    const { uid, exp } = JSON.parse(Buffer.from(payload, 'base64url').toString('utf8'));\n    if (!Number.isInteger(uid) || typeof exp !== 'number' || exp * 1000 < now) return null;\n    return uid;\n  } catch {\n    return null;\n  }\n}\n\nexport function parseCookies(header = '') {\n  const cookies = {};\n  for (const part of String(header).split(';')) {\n    const index = part.indexOf('=');\n    if (index < 0) continue;\n    const name = part.slice(0, index).trim();\n    if (!name || name in cookies) continue;\n    try {\n      cookies[name] = decodeURIComponent(part.slice(index + 1).trim());\n    } catch {\n      cookies[name] = part.slice(index + 1).trim();\n    }\n  }\n  return cookies;\n}\n",
 "backend/src/utils/password.js": "import { randomBytes, scryptSync, timingSafeEqual } from 'node:crypto';\n\nconst KEY_LENGTH = 64;\n\n// Format tersimpan: scrypt$<salt base64>$<hash base64>\nexport function hashPassword(password) {\n  const salt = randomBytes(16);\n  const hash = scryptSync(password, salt, KEY_LENGTH);\n  return `scrypt$${salt.toString('base64')}$${hash.toString('base64')}`;\n}\n\nexport function verifyPassword(password, stored) {\n  if (typeof stored !== 'string') return false;\n  const [scheme, saltB64, hashB64] = stored.split('$');\n  if (scheme !== 'scrypt' || !saltB64 || !hashB64) return false;\n  const expected = Buffer.from(hashB64, 'base64');\n  const actual = scryptSync(password, Buffer.from(saltB64, 'base64'), expected.length);\n  return timingSafeEqual(actual, expected);\n}\n\n// Hash palsu agar waktu respons sama baik email terdaftar maupun tidak\nexport const DUMMY_HASH = hashPassword('tidak-dipakai');\n",
 "backend/src/utils/validators.js": "import { HttpError } from './httpError.js';\n\nexport const CATEGORIES = ['cleanser', 'toner', 'serum', 'moisturizer', 'sunscreen', 'mask', 'other'];\nexport const TIMES = ['morning', 'night'];\nexport const CONDITIONS = ['great', 'good', 'normal', 'dry', 'oily', 'breakout', 'irritated'];\n\n// Format YYYY-MM-DD dan benar-benar tanggal yang ada di kalender (2026-02-31 ditolak).\nexport function isDate(value) {\n  if (typeof value !== 'string' || !/^\\d{4}-\\d{2}-\\d{2}$/.test(value)) return false;\n  const parsed = new Date(value);\n  return !Number.isNaN(parsed.getTime()) && parsed.toISOString().slice(0, 10) === value;\n}\n\nconst isText = (v) => typeof v === 'string' && v.trim().length > 0;\nconst isNonNegInt = (v) => Number.isInteger(v) && v >= 0;\n\nexport function parseId(value, label = 'id') {\n  const id = Number(value);\n  if (!Number.isInteger(id) || id <= 0) {\n    throw new HttpError(400, `${label} harus berupa bilangan bulat positif`);\n  }\n  return id;\n}\n\nexport function validateProduct(body = {}) {\n  const errors = [];\n  if (!isText(body.name)) errors.push('name wajib diisi');\n  if (!isText(body.brand)) errors.push('brand wajib diisi');\n  if (!CATEGORIES.includes(body.category)) {\n    errors.push(`category harus salah satu dari: ${CATEGORIES.join(', ')}`);\n  }\n  if (!isDate(body.expiry_date)) errors.push('expiry_date wajib berformat YYYY-MM-DD');\n  if (body.opened_date != null && !isDate(body.opened_date)) {\n    errors.push('opened_date harus berformat YYYY-MM-DD');\n  }\n  if (isDate(body.opened_date) && isDate(body.expiry_date) && body.opened_date > body.expiry_date) {\n    errors.push('opened_date tidak boleh setelah expiry_date');\n  }\n  const quantity = body.quantity ?? 1;\n  if (!isNonNegInt(quantity)) errors.push('quantity harus bilangan bulat >= 0');\n  if (body.price != null && !isNonNegInt(body.price)) {\n    errors.push('price harus bilangan bulat >= 0');\n  }\n\n  if (errors.length) throw new HttpError(400, 'Validasi gagal', errors);\n\n  return {\n    name: body.name.trim(),\n    brand: body.brand.trim(),\n    category: body.category,\n    opened_date: body.opened_date ?? null,\n    expiry_date: body.expiry_date,\n    quantity,\n    price: body.price ?? null,\n    notes: body.notes ?? null,\n  };\n}\n\nexport function validateRoutine(body = {}) {\n  const errors = [];\n  if (!Number.isInteger(body.product_id) || body.product_id <= 0) {\n    errors.push('product_id wajib berupa bilangan bulat positif');\n  }\n  if (!isDate(body.used_at)) errors.push('used_at wajib berformat YYYY-MM-DD');\n  if (!TIMES.includes(body.time_of_day)) {\n    errors.push(`time_of_day harus salah satu dari: ${TIMES.join(', ')}`);\n  }\n  if (!CONDITIONS.includes(body.skin_condition)) {\n    errors.push(`skin_condition harus salah satu dari: ${CONDITIONS.join(', ')}`);\n  }\n  if (\n    body.skin_rating != null &&\n    !(Number.isInteger(body.skin_rating) && body.skin_rating >= 1 && body.skin_rating <= 5)\n  ) {\n    errors.push('skin_rating harus bilangan bulat 1 sampai 5');\n  }\n\n  if (errors.length) throw new HttpError(400, 'Validasi gagal', errors);\n\n  return {\n    product_id: body.product_id,\n    used_at: body.used_at,\n    time_of_day: body.time_of_day,\n    skin_condition: body.skin_condition,\n    skin_rating: body.skin_rating ?? null,\n    notes: body.notes ?? null,\n  };\n}\n\nconst EMAIL_PATTERN = /^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$/;\n\nexport function validateLogin(body = {}) {\n  const errors = [];\n  const email = typeof body.email === 'string' ? body.email.trim().toLowerCase() : '';\n  const password = typeof body.password === 'string' ? body.password : '';\n\n  if (!email) errors.push('email wajib diisi');\n  else if (email.length > 254 || !EMAIL_PATTERN.test(email)) errors.push('email tidak valid');\n  if (!password) errors.push('password wajib diisi');\n  else if (password.length > 128) errors.push('password maksimal 128 karakter');\n\n  if (errors.length) throw new HttpError(400, 'Validasi gagal', errors);\n  return { email, password };\n}\n",
 "backend/src/routes/authRoutes.js": "import express from 'express';\nimport { authController } from '../controllers/authController.js';\n\nexport function authRoutes(db, secret) {\n  const router = express.Router();\n  const auth = authController(db, secret);\n\n  router.post('/login', auth.login);\n  router.post('/logout', auth.logout);\n  router.get('/me', auth.me);\n\n  return router;\n}\n",
 "backend/tests/auth.test.js": "import { describe, it, expect, beforeAll, afterAll } from 'vitest';\nimport { createApp } from '../src/app.js';\nimport { openDatabase } from '../src/db/database.js';\nimport { hashPassword, verifyPassword } from '../src/utils/password.js';\nimport { createToken, verifyToken, parseCookies } from '../src/utils/session.js';\nimport { validateLogin } from '../src/utils/validators.js';\n\nconst SECRET = 'rahasia-uji';\nlet server;\nlet base;\n\nasync function post(path, body, headers = {}) {\n  const response = await fetch(`${base}${path}`, {\n    method: 'POST',\n    headers: { 'Content-Type': 'application/json', ...headers },\n    body: JSON.stringify(body),\n  });\n  return { response, body: await response.json() };\n}\n\nconst get = async (path, headers = {}) => {\n  const response = await fetch(`${base}${path}`, { headers });\n  return { status: response.status, body: await response.json() };\n};\n\nconst login = (email = 'admin@skincare.test', password = 'Admin123!') =>\n  post('/api/auth/login', { email, password });\n\nbeforeAll(async () => {\n  const app = createApp(openDatabase(':memory:'), { authSecret: SECRET });\n  server = await new Promise((resolve) => {\n    const s = app.listen(0, () => resolve(s));\n  });\n  base = `http://127.0.0.1:${server.address().port}`;\n});\n\nafterAll(() => new Promise((resolve) => server.close(resolve)));\n\ndescribe('POST /api/auth/login', () => {\n  it('masuk dengan email dan password benar, cookie sesi httpOnly diset', async () => {\n    const { response, body } = await login();\n    expect(response.status).toBe(200);\n    expect(body.data.user.email).toBe('admin@skincare.test');\n    expect(body.data.user.password_hash).toBeUndefined();\n\n    const cookie = response.headers.get('set-cookie');\n    expect(cookie).toContain('session=');\n    expect(cookie).toContain('HttpOnly');\n    expect(cookie).toContain('SameSite=Lax');\n  });\n\n  it('tidak membedakan huruf besar kecil dan spasi pada email', async () => {\n    const { response } = await login('  ADMIN@Skincare.Test ');\n    expect(response.status).toBe(200);\n  });\n\n  it('menolak password salah dan email tidak terdaftar dengan pesan yang sama', async () => {\n    const wrongPassword = await login('admin@skincare.test', 'salah-banget');\n    const unknownEmail = await login('tidak.ada@skincare.test', 'Admin123!');\n    expect(wrongPassword.response.status).toBe(401);\n    expect(unknownEmail.response.status).toBe(401);\n    expect(wrongPassword.body.message).toBe('Email atau kata sandi salah');\n    expect(unknownEmail.body.message).toBe(wrongPassword.body.message);\n    expect(wrongPassword.response.headers.get('set-cookie')).toBeNull();\n  });\n\n  it('menolak input tidak valid dengan 400', async () => {\n    const empty = await post('/api/auth/login', {});\n    expect(empty.response.status).toBe(400);\n    expect(empty.body.errors).toContain('email wajib diisi');\n    expect(empty.body.errors).toContain('password wajib diisi');\n\n    const badEmail = await login('bukan-email', 'x');\n    expect(badEmail.response.status).toBe(400);\n    expect(badEmail.body.errors).toContain('email tidak valid');\n\n    const notText = await post('/api/auth/login', { email: 123, password: ['a'] });\n    expect(notText.response.status).toBe(400);\n  });\n\n  it('memblokir sementara setelah 5 kali gagal untuk email yang sama', async () => {\n    const email = 'korban@skincare.test';\n    for (let i = 0; i < 5; i += 1) {\n      expect((await login(email, 'salah')).response.status).toBe(401);\n    }\n    expect((await login(email, 'salah')).response.status).toBe(429);\n    // email lain tidak ikut terblokir\n    expect((await login()).response.status).toBe(200);\n  });\n});\n\ndescribe('akses endpoint terproteksi', () => {\n  it('menolak permintaan tanpa cookie sesi', async () => {\n    for (const path of ['/api/products', '/api/routines', '/api/products/1/routines']) {\n      const { status, body } = await get(path);\n      expect(status).toBe(401);\n      expect(body.success).toBe(false);\n    }\n  });\n\n  it('/api/auth/me membalas 200 dengan user null untuk pengunjung (tanpa error di console browser)', async () => {\n    const { status, body } = await get('/api/auth/me');\n    expect(status).toBe(200);\n    expect(body.data.user).toBeNull();\n    const forged = await get('/api/auth/me', { Cookie: 'session=abc' });\n    expect(forged.body.data.user).toBeNull();\n  });\n\n  it('tetap membuka /api/health tanpa login', async () => {\n    expect((await get('/api/health')).status).toBe(200);\n  });\n\n  it('mengizinkan akses dengan cookie sesi dan mengembalikan profil di /me', async () => {\n    const { response } = await login();\n    const cookie = response.headers.get('set-cookie').split(';')[0];\n\n    const products = await get('/api/products', { Cookie: cookie });\n    expect(products.status).toBe(200);\n\n    const me = await get('/api/auth/me', { Cookie: cookie });\n    expect(me.status).toBe(200);\n    expect(me.body.data.user.name).toBe('Pengguna Uji');\n  });\n\n  it('menolak cookie palsu, rusak, dan yang ditandatangani kunci lain', async () => {\n    const forged = createToken(1, 'kunci-lain');\n    for (const value of ['session=abc', `session=${forged}`, 'session=', 'lain=1']) {\n      expect((await get('/api/products', { Cookie: value })).status).toBe(401);\n    }\n  });\n\n  it('menolak sesi milik pengguna yang sudah tidak ada', async () => {\n    const ghost = createToken(9999, SECRET);\n    expect((await get('/api/products', { Cookie: `session=${ghost}` })).status).toBe(401);\n  });\n});\n\ndescribe('POST /api/auth/logout', () => {\n  it('menghapus cookie sesi', async () => {\n    const { response, body } = await post('/api/auth/logout', {});\n    expect(response.status).toBe(200);\n    expect(body.data.loggedOut).toBe(true);\n    expect(response.headers.get('set-cookie')).toMatch(/session=;/);\n  });\n});\n\ndescribe('utilitas password', () => {\n  it('hash berbeda tiap kali (salt acak) tetapi sama-sama bisa diverifikasi', () => {\n    const a = hashPassword('rahasia');\n    const b = hashPassword('rahasia');\n    expect(a).not.toBe(b);\n    expect(verifyPassword('rahasia', a)).toBe(true);\n    expect(verifyPassword('RAHASIA', a)).toBe(false);\n  });\n\n  it('menolak format hash yang tidak dikenal', () => {\n    expect(verifyPassword('x', undefined)).toBe(false);\n    expect(verifyPassword('x', 'plain-text')).toBe(false);\n    expect(verifyPassword('x', 'bcrypt$a$b')).toBe(false);\n  });\n});\n\ndescribe('utilitas sesi', () => {\n  it('token valid mengembalikan id dan kedaluwarsa setelah 7 hari', () => {\n    const now = Date.now();\n    const token = createToken(7, SECRET, now);\n    expect(verifyToken(token, SECRET, now)).toBe(7);\n    expect(verifyToken(token, SECRET, now + 6 * 86400000)).toBe(7);\n    expect(verifyToken(token, SECRET, now + 8 * 86400000)).toBeNull();\n  });\n\n  it('menolak token yang diubah, berformat salah, atau bukan string', () => {\n    const token = createToken(7, SECRET);\n    const [payload, signature] = token.split('.');\n    const tampered = Buffer.from(JSON.stringify({ uid: 1, exp: 9999999999 })).toString('base64url');\n    expect(verifyToken(`${tampered}.${signature}`, SECRET)).toBeNull();\n    expect(verifyToken(`${payload}.`, SECRET)).toBeNull();\n    expect(verifyToken(`${payload}.pendek`, SECRET)).toBeNull();\n    expect(verifyToken(undefined, SECRET)).toBeNull();\n    expect(verifyToken('tanpa-titik', SECRET)).toBeNull();\n  });\n\n  it('menolak payload yang bertanda tangan benar tetapi isinya tidak masuk akal', async () => {\n    const { createHmac } = await import('node:crypto');\n    const forge = (raw) => {\n      const payload = Buffer.from(raw).toString('base64url');\n      return `${payload}.${createHmac('sha256', SECRET).update(payload).digest('base64url')}`;\n    };\n    expect(verifyToken(forge('bukan json'), SECRET)).toBeNull();\n    expect(verifyToken(forge(JSON.stringify({ uid: 'satu', exp: 9999999999 })), SECRET)).toBeNull();\n  });\n\n  it('membaca cookie dengan benar', () => {\n    expect(parseCookies('a=1; session=abc%20d; b=2')).toEqual({ a: '1', session: 'abc d', b: '2' });\n    expect(parseCookies('rusak; =x; c=%E0%A4%A')).toEqual({ c: '%E0%A4%A' });\n    expect(parseCookies(undefined)).toEqual({});\n  });\n});\n\ndescribe('validateLogin', () => {\n  it('menormalkan email dan menolak password terlalu panjang', () => {\n    expect(validateLogin({ email: ' A@B.co ', password: 'x' })).toEqual({ email: 'a@b.co', password: 'x' });\n    expect(() => validateLogin({ email: 'a@b.co', password: 'x'.repeat(129) })).toThrow('Validasi gagal');\n    expect(() => validateLogin()).toThrow('Validasi gagal');\n  });\n});\n",
 "backend/tests/db.test.js": "import { describe, it, expect } from 'vitest';\nimport { mkdtempSync, rmSync } from 'node:fs';\nimport { tmpdir } from 'node:os';\nimport { join } from 'node:path';\nimport { openDatabase } from '../src/db/database.js';\n\nconst count = (db, table) => db.prepare(`SELECT COUNT(*) AS n FROM ${table}`).get().n;\n\ndescribe('openDatabase', () => {\n  it('membuat skema dan mengisi dummy data produk nyata', () => {\n    const db = openDatabase(':memory:');\n    expect(count(db, 'products')).toBe(5);\n    expect(count(db, 'routines')).toBe(9);\n\n    const names = db.prepare('SELECT name FROM products').all().map((row) => row.name);\n    expect(names).toContain('Wardah Facial Wash');\n    expect(names).toContain('Implora Sunscreen SPF 40++');\n    expect(names).toContain('Glowies Dreamy Moisturizer');\n  });\n\n  it('tidak mengisi dummy data jika seed dimatikan', () => {\n    const db = openDatabase(':memory:', { seed: false });\n    expect(count(db, 'products')).toBe(0);\n    expect(count(db, 'users')).toBe(0);\n  });\n\n  it('membuat akun uji dengan password ter-hash', () => {\n    const db = openDatabase(':memory:');\n    const user = db.prepare('SELECT * FROM users').get();\n    expect(count(db, 'users')).toBe(1);\n    expect(user.email).toBe('admin@skincare.test');\n    expect(user.password_hash.startsWith('scrypt$')).toBe(true);\n    expect(user.password_hash).not.toContain('Admin123!');\n  });\n\n  it('get mengembalikan undefined jika baris tidak ada', () => {\n    const db = openDatabase(':memory:');\n    expect(db.prepare('SELECT * FROM products WHERE id = ?').get(9999)).toBeUndefined();\n  });\n\n  it('menghapus produk ikut menghapus jurnalnya (ON DELETE CASCADE)', () => {\n    const db = openDatabase(':memory:');\n    const before = db.prepare('SELECT COUNT(*) AS n FROM routines WHERE product_id = 1').get().n;\n    expect(before).toBeGreaterThan(0);\n\n    db.prepare('DELETE FROM products WHERE id = ?').run(1);\n    expect(db.prepare('SELECT COUNT(*) AS n FROM routines WHERE product_id = 1').get().n).toBe(0);\n  });\n\n  it('menolak jurnal untuk produk yang tidak ada (foreign key)', () => {\n    const db = openDatabase(':memory:');\n    const insert = () =>\n      db\n        .prepare(\n          `INSERT INTO routines (product_id, used_at, time_of_day, skin_condition)\n           VALUES (?, '2026-10-22', 'morning', 'good')`\n        )\n        .run(9999);\n    expect(insert).toThrow();\n  });\n\n  it('membuat file database di folder baru dan tidak menggandakan seed saat dibuka ulang', () => {\n    const dir = mkdtempSync(join(tmpdir(), 'skincare-'));\n    const file = join(dir, 'nested', 'test.db');\n    try {\n      const first = openDatabase(file);\n      expect(count(first, 'products')).toBe(5);\n      first.close();\n\n      const second = openDatabase(file);\n      expect(count(second, 'products')).toBe(5);\n      second.close();\n    } finally {\n      rmSync(dir, { recursive: true, force: true });\n    }\n  });\n});\n",
 "backend/tests/api.test.js": "import { describe, it, expect, beforeAll, afterAll } from 'vitest';\nimport { createApp } from '../src/app.js';\nimport { openDatabase } from '../src/db/database.js';\n\nlet server;\nlet base;\nlet cookie = '';\n\nasync function start(app) {\n  const instance = await new Promise((resolve) => {\n    const s = app.listen(0, () => resolve(s));\n  });\n  return { instance, url: `http://127.0.0.1:${instance.address().port}` };\n}\n\nconst stop = (instance) => new Promise((resolve) => instance.close(resolve));\n\nasync function call(path, { method = 'GET', body, raw } = {}) {\n  const response = await fetch(`${base}${path}`, {\n    method,\n    headers: { 'Content-Type': 'application/json', ...(cookie && { Cookie: cookie }) },\n    body: raw ?? (body === undefined ? undefined : JSON.stringify(body)),\n  });\n  return { status: response.status, body: await response.json() };\n}\n\nconst isoFromNow = (days) => new Date(Date.now() + days * 86400000).toISOString().slice(0, 10);\n\nconst newProduct = (overrides = {}) => ({\n  name: 'Hada Labo Gokujyun Lotion',\n  brand: 'Hada Labo',\n  category: 'toner',\n  expiry_date: isoFromNow(400),\n  price: 85000,\n  ...overrides,\n});\n\nbeforeAll(async () => {\n  const started = await start(createApp(openDatabase(':memory:')));\n  server = started.instance;\n  base = started.url;\n\n  // Semua endpoint data butuh sesi login, masuk dengan akun seed\n  const login = await fetch(`${base}/api/auth/login`, {\n    method: 'POST',\n    headers: { 'Content-Type': 'application/json' },\n    body: JSON.stringify({ email: 'admin@skincare.test', password: 'Admin123!' }),\n  });\n  cookie = login.headers.get('set-cookie').split(';')[0];\n});\n\nafterAll(() => stop(server));\n\ndescribe('GET /api/health', () => {\n  it('mengembalikan status ok', async () => {\n    const { status, body } = await call('/api/health');\n    expect(status).toBe(200);\n    expect(body.data.status).toBe('ok');\n  });\n});\n\ndescribe('Products API', () => {\n  it('mengembalikan semua produk beserta days_left', async () => {\n    const { status, body } = await call('/api/products');\n    expect(status).toBe(200);\n    expect(body.success).toBe(true);\n    expect(body.data.length).toBeGreaterThanOrEqual(5);\n    expect(typeof body.data[0].days_left).toBe('number');\n  });\n\n  it('memfilter berdasarkan category dan search', async () => {\n    const byCategory = await call('/api/products?category=sunscreen');\n    expect(byCategory.body.data).toHaveLength(1);\n    expect(byCategory.body.data[0].name).toBe('Implora Sunscreen SPF 40++');\n\n    const bySearch = await call('/api/products?search=wardah');\n    expect(bySearch.body.data).toHaveLength(2);\n\n    const combined = await call('/api/products?category=cleanser&search=wardah');\n    expect(combined.body.data).toHaveLength(1);\n  });\n\n  it('memfilter produk yang segera kedaluwarsa', async () => {\n    const soon = await call('/api/products', {\n      method: 'POST',\n      body: newProduct({ name: 'Produk Hampir Habis', expiry_date: isoFromNow(10) }),\n    });\n    const later = await call('/api/products', {\n      method: 'POST',\n      body: newProduct({ name: 'Produk Masih Lama', expiry_date: isoFromNow(400) }),\n    });\n    expect(soon.status).toBe(201);\n    expect(later.status).toBe(201);\n\n    const { body } = await call('/api/products?expiring=30');\n    const names = body.data.map((p) => p.name);\n    expect(names).toContain('Produk Hampir Habis');\n    expect(names).not.toContain('Produk Masih Lama');\n\n    const invalid = await call('/api/products?expiring=abc');\n    expect(invalid.status).toBe(400);\n  });\n\n  it('mengambil satu produk, 404 jika tidak ada, 400 jika id salah', async () => {\n    const found = await call('/api/products/1');\n    expect(found.status).toBe(200);\n    expect(found.body.data.name).toBe('Wardah Facial Wash');\n\n    expect((await call('/api/products/9999')).status).toBe(404);\n    expect((await call('/api/products/abc')).status).toBe(400);\n  });\n\n  it('membuat, mengubah, lalu menghapus produk', async () => {\n    const created = await call('/api/products', { method: 'POST', body: newProduct() });\n    expect(created.status).toBe(201);\n    expect(created.body.data.quantity).toBe(1);\n    const id = created.body.data.id;\n\n    const updated = await call(`/api/products/${id}`, {\n      method: 'PUT',\n      body: newProduct({ name: 'Hada Labo Premium', quantity: 3 }),\n    });\n    expect(updated.status).toBe(200);\n    expect(updated.body.data.name).toBe('Hada Labo Premium');\n    expect(updated.body.data.quantity).toBe(3);\n\n    const removed = await call(`/api/products/${id}`, { method: 'DELETE' });\n    expect(removed.status).toBe(200);\n    expect((await call(`/api/products/${id}`)).status).toBe(404);\n  });\n\n  it('menolak data tidak valid dan produk yang tidak ada', async () => {\n    const invalid = await call('/api/products', { method: 'POST', body: { name: '' } });\n    expect(invalid.status).toBe(400);\n    expect(invalid.body.success).toBe(false);\n    expect(invalid.body.errors.length).toBeGreaterThan(0);\n\n    expect((await call('/api/products/9999', { method: 'PUT', body: newProduct() })).status).toBe(404);\n    expect((await call('/api/products/9999', { method: 'DELETE' })).status).toBe(404);\n    expect((await call('/api/products/1', { method: 'PUT', body: {} })).status).toBe(400);\n  });\n\n  it('menolak body JSON yang rusak', async () => {\n    const { status, body } = await call('/api/products', { method: 'POST', raw: '{rusak' });\n    expect(status).toBe(400);\n    expect(body.message).toBe('Body JSON tidak valid');\n  });\n\n  it('menghapus produk ikut menghapus jurnalnya', async () => {\n    const product = await call('/api/products', { method: 'POST', body: newProduct() });\n    const productId = product.body.data.id;\n    const routine = await call('/api/routines', {\n      method: 'POST',\n      body: { product_id: productId, used_at: '2026-10-22', time_of_day: 'night', skin_condition: 'good' },\n    });\n    expect(routine.status).toBe(201);\n\n    await call(`/api/products/${productId}`, { method: 'DELETE' });\n    expect((await call(`/api/routines/${routine.body.data.id}`)).status).toBe(404);\n  });\n});\n\ndescribe('Routines API', () => {\n  const newRoutine = (overrides = {}) => ({\n    product_id: 1,\n    used_at: '2026-10-22',\n    time_of_day: 'night',\n    skin_condition: 'good',\n    skin_rating: 4,\n    notes: 'Kulit terasa lembap',\n    ...overrides,\n  });\n\n  it('mengembalikan jurnal beserta nama produk', async () => {\n    const { status, body } = await call('/api/routines');\n    expect(status).toBe(200);\n    expect(body.data.length).toBeGreaterThanOrEqual(9);\n    expect(typeof body.data[0].product_name).toBe('string');\n  });\n\n  it('memfilter berdasarkan date, time_of_day, dan product_id', async () => {\n    const byDate = await call('/api/routines?date=2026-10-20');\n    expect(byDate.body.data).toHaveLength(5);\n\n    const byTime = await call('/api/routines?date=2026-10-20&time_of_day=night');\n    expect(byTime.body.data).toHaveLength(2);\n\n    const byProduct = await call('/api/routines?product_id=5');\n    expect(byProduct.body.data).toHaveLength(2);\n  });\n\n  it('menolak filter yang tidak valid', async () => {\n    expect((await call('/api/routines?date=kemarin')).status).toBe(400);\n    expect((await call('/api/routines?time_of_day=siang')).status).toBe(400);\n    expect((await call('/api/routines?product_id=abc')).status).toBe(400);\n  });\n\n  it('mengambil jurnal milik satu produk', async () => {\n    const { status, body } = await call('/api/products/2/routines');\n    expect(status).toBe(200);\n    expect(body.data).toHaveLength(2);\n    expect((await call('/api/products/9999/routines')).status).toBe(404);\n    expect((await call('/api/products/abc/routines')).status).toBe(400);\n  });\n\n  it('mengambil satu jurnal, 404 jika tidak ada', async () => {\n    const found = await call('/api/routines/1');\n    expect(found.status).toBe(200);\n    expect(found.body.data.product_id).toBe(1);\n    expect((await call('/api/routines/9999')).status).toBe(404);\n  });\n\n  it('membuat, mengubah, lalu menghapus jurnal', async () => {\n    const created = await call('/api/routines', { method: 'POST', body: newRoutine() });\n    expect(created.status).toBe(201);\n    expect(created.body.data.product_name).toBe('Wardah Facial Wash');\n    const id = created.body.data.id;\n\n    const updated = await call(`/api/routines/${id}`, {\n      method: 'PUT',\n      body: newRoutine({ skin_condition: 'great', skin_rating: 5 }),\n    });\n    expect(updated.status).toBe(200);\n    expect(updated.body.data.skin_condition).toBe('great');\n\n    const removed = await call(`/api/routines/${id}`, { method: 'DELETE' });\n    expect(removed.status).toBe(200);\n    expect((await call(`/api/routines/${id}`)).status).toBe(404);\n  });\n\n  it('menolak jurnal yang tidak valid atau produk yang tidak ada', async () => {\n    const invalid = await call('/api/routines', { method: 'POST', body: { product_id: 1 } });\n    expect(invalid.status).toBe(400);\n\n    const unknownProduct = await call('/api/routines', {\n      method: 'POST',\n      body: newRoutine({ product_id: 9999 }),\n    });\n    expect(unknownProduct.status).toBe(400);\n\n    expect((await call('/api/routines/9999', { method: 'PUT', body: newRoutine() })).status).toBe(404);\n    expect(\n      (await call('/api/routines/1', { method: 'PUT', body: newRoutine({ product_id: 9999 }) })).status\n    ).toBe(400);\n    expect((await call('/api/routines/9999', { method: 'DELETE' })).status).toBe(404);\n  });\n});\n\ndescribe('Penanganan error', () => {\n  it('mengembalikan 404 JSON untuk endpoint yang tidak dikenal', async () => {\n    const { status, body } = await call('/api/tidak-ada');\n    expect(status).toBe(404);\n    expect(body.success).toBe(false);\n  });\n\n  it('mengembalikan 500 untuk error yang tidak terduga', async () => {\n    const brokenDb = {\n      prepare() {\n        throw new Error('database rusak');\n      },\n    };\n    const started = await start(createApp(brokenDb));\n    const original = console.error;\n    console.error = () => {};\n    try {\n      const response = await fetch(`${started.url}/api/health`);\n      const body = await response.json();\n      expect(response.status).toBe(500);\n      expect(body.message).toBe('Terjadi kesalahan pada server');\n    } finally {\n      console.error = original;\n      await stop(started.instance);\n    }\n  });\n});\n",
 "backend/tests/static.test.js": "import { describe, it, expect, beforeAll, afterAll } from 'vitest';\nimport { mkdtempSync, writeFileSync, rmSync } from 'node:fs';\nimport { tmpdir } from 'node:os';\nimport { join } from 'node:path';\nimport { createApp } from '../src/app.js';\nimport { openDatabase } from '../src/db/database.js';\n\nconst listen = (app) =>\n  new Promise((resolve) => {\n    const s = app.listen(0, () => resolve(s));\n  });\nconst close = (s) => new Promise((resolve) => s.close(resolve));\n\nlet dir;\nlet withStatic;\nlet withoutStatic;\nlet staticUrl;\nlet plainUrl;\n\nbeforeAll(async () => {\n  dir = mkdtempSync(join(tmpdir(), 'skincare-dist-'));\n  writeFileSync(join(dir, 'index.html'), '<!doctype html><title>Skincare</title><div id=\"app\"></div>');\n\n  withStatic = await listen(createApp(openDatabase(':memory:'), { staticDir: dir }));\n  withoutStatic = await listen(createApp(openDatabase(':memory:')));\n  staticUrl = `http://127.0.0.1:${withStatic.address().port}`;\n  plainUrl = `http://127.0.0.1:${withoutStatic.address().port}`;\n});\n\nafterAll(async () => {\n  await close(withStatic);\n  await close(withoutStatic);\n  rmSync(dir, { recursive: true, force: true });\n});\n\ndescribe('menyajikan hasil build Vue', () => {\n  it('mengembalikan index.html pada halaman utama', async () => {\n    const response = await fetch(`${staticUrl}/`);\n    expect(response.status).toBe(200);\n    expect(await response.text()).toContain('<div id=\"app\">');\n  });\n\n  it('memakai fallback index.html untuk rute non-API', async () => {\n    const response = await fetch(`${staticUrl}/halaman-apa-saja`);\n    expect(response.status).toBe(200);\n    expect(await response.text()).toContain('<title>Skincare</title>');\n  });\n\n  it('tetap mengembalikan JSON untuk API dan 404 untuk metode selain GET', async () => {\n    const health = await fetch(`${staticUrl}/api/health`);\n    expect((await health.json()).success).toBe(true);\n\n    const products = await fetch(`${staticUrl}/api/products`);\n    expect(products.status).toBe(401);\n\n    const unknown = await fetch(`${staticUrl}/api/tidak-ada`);\n    expect(unknown.status).toBe(404);\n\n    const post = await fetch(`${staticUrl}/halaman-apa-saja`, { method: 'POST' });\n    expect(post.status).toBe(404);\n  });\n});\n\ndescribe('tanpa folder dist', () => {\n  it('mengembalikan 404 JSON untuk halaman utama', async () => {\n    const response = await fetch(`${plainUrl}/`);\n    expect(response.status).toBe(404);\n    expect((await response.json()).success).toBe(false);\n  });\n});\n",
 "api/index.js": "// Titik masuk Vercel: seluruh permintaan /api/* diteruskan ke aplikasi Express yang sama dengan server lokal.\nimport { tmpdir } from 'node:os';\nimport { join } from 'node:path';\nimport { createApp } from '../backend/src/app.js';\nimport { openDatabase } from '../backend/src/db/database.js';\n\n// Vercel hanya mengizinkan menulis di folder sementara, jadi database SQLite ditaruh di sana.\n// Isinya hilang saat fungsi dimulai ulang dan terisi dummy data lagi (SEED=false untuk menonaktifkan).\nconst dbPath = process.env.DB_PATH || join(tmpdir(), 'skincare.db');\nconst db = openDatabase(dbPath, { seed: process.env.SEED !== 'false' });\n\n// AUTH_SECRET wajib diisi di Vercel agar cookie login valid di semua instance fungsi.\nexport default createApp(db, { authSecret: process.env.AUTH_SECRET || undefined });"
};

const APPENDS = {
 "frontend/src/styles/global.css": {
  "marker": "Login & routing",
  "text": "\n\n/* ===== Login & routing: kerangka isi halaman dan tautan bergaya tombol ===== */\n.page {\n  display: grid;\n  gap: 1.5rem;\n  padding: 1.5rem 0 3rem;\n}\na.btn {\n  text-decoration: none;\n}\n"
 },
 "backend/.env.example": {
  "marker": "AUTH_SECRET",
  "text": "\n\n# Kunci penanda tangan cookie login. Isi string acak panjang (openssl rand -hex 32).\n# Jika kosong, kunci dibuat acak tiap server start sehingga semua sesi berakhir saat restart.\n# WAJIB diisi di Vercel.\nAUTH_SECRET=\n# Akun uji yang dibuat otomatis saat tabel users masih kosong (hanya jika SEED=true)\nSEED_USER_EMAIL=admin@skincare.test\nSEED_USER_PASSWORD=Admin123!\n# Set true jika dilayani lewat HTTPS (otomatis aktif di Vercel)\nCOOKIE_SECURE=false\n"
 },
 "README.md": {
  "marker": "## Login (email",
  "text": "\n\n## Login (email dan kata sandi)\n\nAplikasi sekarang memakai login. Halaman publik: `/` dan `/auth/login`. Halaman yang butuh login: `/produk`, `/jurnal`, `/ringkasan`, `/profil`.\n\nAkun uji dibuat otomatis saat tabel `users` masih kosong (hanya jika `SEED` tidak `false`):\n\n| Email | Kata sandi |\n|---|---|\n| `admin@skincare.test` | `Admin123!` |\n\nEndpoint: `POST /api/auth/login`, `POST /api/auth/logout`, `GET /api/auth/me`. Endpoint `/api/products` dan `/api/routines` membalas 401 jika belum login. Variabel `.env` tambahan: `AUTH_SECRET`, `SEED_USER_EMAIL`, `SEED_USER_PASSWORD`, `COOKIE_SECURE` (lihat `backend/.env.example`).\n\n**Vercel:** isi `AUTH_SECRET` (string acak panjang) di Project Settings, Environment Variables, lalu redeploy. Tanpa itu, login bisa gagal karena tiap instance fungsi membuat kunci acak sendiri.\n"
 }
};

const root = process.cwd();
if (!existsSync(join(root, 'backend', 'src', 'app.js')) || !existsSync(join(root, 'frontend', 'src', 'App.vue'))) {
  console.error('GAGAL: jalankan skrip ini dari folder root proyek (yang berisi folder backend dan frontend).');
  process.exit(1);
}

const BACKUP = join(root, '.login-backup');
let written = 0;
let backedUp = 0;

for (const [rel, content] of Object.entries(FILES)) {
  const target = join(root, rel);
  if (existsSync(target)) {
    const old = readFileSync(target, 'utf8');
    if (old === content) continue;
    const copy = join(BACKUP, rel);
    mkdirSync(dirname(copy), { recursive: true });
    writeFileSync(copy, old);
    backedUp += 1;
  }
  mkdirSync(dirname(target), { recursive: true });
  writeFileSync(target, content);
  written += 1;
  console.log('  tulis   ', rel);
}

for (const [rel, { marker, text }] of Object.entries(APPENDS)) {
  const target = join(root, rel);
  if (!existsSync(target)) continue;
  const old = readFileSync(target, 'utf8');
  if (old.includes(marker)) {
    console.log('  lewati  ', rel, '(sudah ada)');
    continue;
  }
  writeFileSync(target, old.replace(/\s*$/, '') + text);
  console.log('  tambah  ', rel);
}

const pkgPath = join(root, 'frontend', 'package.json');
const pkg = JSON.parse(readFileSync(pkgPath, 'utf8'));
if (!pkg.dependencies['vue-router']) {
  pkg.dependencies['vue-router'] = '^4.5.0';
  writeFileSync(pkgPath, JSON.stringify(pkg, null, 2) + '\n');
  console.log('  tambah   frontend/package.json (vue-router)');
}

console.log(`\nSelesai: ${written} file ditulis` + (backedUp ? `, ${backedUp} file lama dicadangkan di .login-backup/` : '') + '.');
console.log('Langkah berikutnya:  npm install  ->  npm test  ->  npm run build  ->  npm start');
